["HELM_BP_S4_SCRIPTWRITER"]="¡Luces, cámara, acción!",
["ARMOR_BP_S4_SCRIPTWRITER"]="La cuarta pared",
["WEAPON_BP_S4_SCRIPTWRITER"]="¡No te metas con el director!",
